class ConfCamposReporteCorreo extends BaseConfCamposReporteCorreo
{
    public function fnObtenerReporteCorreoXIdCampoReporte($idcamporeportecorreo)
    {
        return Doctrine::getTable('ConfCamposReporteCorreo')->find($idcamporeportecorreo);
    }

    public function fnObtenerReporteCorreoXIdEntidad($identidad)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sqlData = "select ccrc.*,ccrce.*
                    from mod_nomina.conf_camposreportecorreo ccrc
                    inner join mod_nomina.conf_camposreportecorreoentidad ccrce on (ccrce.idcamporeportecorreo = ccrc.idcamporeportecorreo)
                    where ccrce.identidad = ? ORDER BY ccrc.orden ASC;";
        $r = $conn->fetchAll($sqlData, array($identidad));
        return $r;
    }

    public function fnObtenerOrdenDisponible($identidad)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $sql = "select MAX(ccrc.orden) as orden
			from mod_nomina.conf_camposreportecorreo ccrc
			inner join mod_nomina.conf_camposreportecorreoentidad ccrce on (ccrce.idcamporeportecorreo = ccrc.idcamporeportecorreo)
			where ccrce.identidad = ?";
        $r = $conn->fetchAll($sql, array($identidad));
        $r[0]['orden'] = !empty($r) ? $r[0]['orden'] + 1 : 1;
        return $r[0];
    }

    public function fnBuscarCampoXDenominacion($denominacion)
    {
        try {
            $mg = Doctrine_Manager::getInstance();
            $conn = $mg->getCurrentConnection();
            $sql = "SELECT COUNT(ccrc.*)
                FROM  mod_nomina.conf_camposreportecorreo ccrc
                WHERE ccrc.denominacion ilike '%{$denominacion}%'";
            $result = $conn->fetchOne($sql);
            return $result;
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

    public function fnAdicionarConfCamposReporteCorreo($params)
    {
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();

        $existecampo = $this->fnBuscarCampoXDenominacion($params['denominacion']);
        if ($existecampo == 0) {
            $sql = "INSERT INTO mod_nomina.conf_camposreportecorreo(denominacion,idformula,orden,descripcion,mostrarvacaciones,mostrarsnc,estotal)
                    VALUES (
                    '" . $params['denominacion'] . "',
                    {$params['idformula']},
                    {$params['orden']},
                    '" . $params['descripcion'] . "',
                    {$params['mostrarvacaciones']},
                    {$params['mostrarsnc']},
                    {$params['estotal']}) returning idcamporeportecorreo;";
            $r = $conn->fetchAll($sql);
            $idcamporeportecorreo = $r[0]['idcamporeportecorreo'];

            $sql = "INSERT INTO mod_nomina.conf_camposreportecorreoentidad(identidad,idcamporeportecorreo)
                VALUES ({$params['identidad']},{$idcamporeportecorreo});";
            $conn->fetchAll($sql);
            return 1;
        } else
            return 2;
    }

    public function fnModificarConfCamposReporteCorreo($params)
    {
        $obj = $this->fnObtenerReporteCorreoXIdCampoReporte($params['idcamporeportecorreo']);
        $obj->denominacion = $params['denominacion'];
        $obj->orden = $params['orden'];
        $obj->mostrarvacaciones = $params['mostrarvacaciones'];
        $obj->mostrarsnc = $params['mostrarsnc'];
        $obj->idformula = $params['idformula'];
        $obj->descripcion = $params['descripcion'];
        $obj->estotal = $params['estotal'];
        $obj->save();
        return 1;
    }

    public function fnEliminarConfCamposReporteCorreo($params)
    {
        $objentidad = new ConfCamposReporteCorreoEntidad();
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $conn->beginTransaction();
        $arridcamporeportecorreo = implode(',', $params['idcamporeportecorreo']);
        $sql = "DELETE FROM mod_nomina.conf_camposreportecorreoentidad WHERE identidad = ? AND idcamporeportecorreo IN ({$arridcamporeportecorreo});";
        $conn->execute($sql, array($params['identidad']));

        foreach ($params['idcamporeportecorreo'] as $idcamporeportecorreo) {
            $cont = $objentidad->fnObtenerCantConfXIdReporte($idcamporeportecorreo);
            if ($cont == 0) {
                $sql = "DELETE FROM mod_nomina.conf_camposreportecorreo WHERE idcamporeportecorreo = ?;";
                $conn->execute($sql, array($idcamporeportecorreo));
            }
        }
        $conn->commit();
        return 1;
    }

    public function fnReplicarCamposReporteCorreo($params)
    {
        $objentidad = new ConfCamposReporteCorreoEntidad();
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $conn->beginTransaction();
        foreach ($params['arridentidad'] as $identidad) {
            foreach ($params['arridcamporeportecorreo'] as $idcamporeportecorreo) {
                $cont = $objentidad->fnObtenerCantConfXIdReporteIdEntidad($identidad, $idcamporeportecorreo);
                if ($cont == 0) {
                    $sql = "INSERT INTO mod_nomina.conf_camposreportecorreoentidad(identidad,idcamporeportecorreo)
                            VALUES ({$identidad},{$idcamporeportecorreo});";
                    $conn->fetchAll($sql);
                }
            }
        }
        $conn->commit();
        return 1;
    }
}
